  public static bool Has(string key) => Language == "en-US" ? En.ContainsKey(key) || Zh.ContainsKey(key) : Zh.ContainsKey(key);

  // Exact language match first, then the Chinese fallback, then the key itself so a missing
  // translation surfaces as its code instead of an empty label.
  public static string Get(string key)
  {
    var table = Language == "en-US" ? En : Zh;
    if (table.TryGetValue(key, out var text)) return text;
    return Zh.TryGetValue(key, out text) ? text : key;
  }
}
